const survey = $('HTTP Request').item.json;
const allRows = $input.all().map(i => i.json);

function round2(n) {
  return Math.round(n * 100) / 100;
}

const output = [];

for (const question of survey.questions) {
  const rows = allRows.filter(r => r.question_id === question.id);

  const type = question.type;
  let totalResponses = 0;
  let frequencyTable = {};
  let percentageTable = {};
  let average = null;
  let mode = null;
  let min = null;
  let max = null;

  if (type === 'SINGLE_CHOICE' || type === 'FREQUENCY' || type === 'MULTIPLE_CHOICE') {
    const uniqueResponses = new Set(rows.map(r => r.response_id));
    totalResponses = uniqueResponses.size;

    for (const opt of question.options || []) {
      frequencyTable[opt.text] = 0;
    }
    for (const row of rows) {
      if (row.option_label) {
        frequencyTable[row.option_label] = (frequencyTable[row.option_label] || 0) + 1;
      }
    }
    for (const key in frequencyTable) {
      percentageTable[key] = totalResponses > 0 ? round2((frequencyTable[key] / totalResponses) * 100) : 0;
    }
    let maxFreq = -1;
    mode = [];
    for (const key in frequencyTable) {
      if (frequencyTable[key] > maxFreq) {
        maxFreq = frequencyTable[key];
        mode = [key];
      } else if (frequencyTable[key] === maxFreq && maxFreq > 0) {
        mode.push(key);
      }
    }
  } else if (type === 'YES_NO') {
    totalResponses = rows.length;
    frequencyTable = { Si: 0, No: 0 };
    for (const row of rows) {
      if (Number(row.numeric_value) === 1) frequencyTable['Si']++;
      else frequencyTable['No']++;
    }
    for (const key in frequencyTable) {
      percentageTable[key] = totalResponses > 0 ? round2((frequencyTable[key] / totalResponses) * 100) : 0;
    }
    mode = frequencyTable['Si'] >= frequencyTable['No'] ? ['Si'] : ['No'];
  } else if (type === 'SCALE_1_5' || type === 'RATING_1_5') {
    const values = rows.map(r => Number(r.numeric_value));
    totalResponses = values.length;

    for (let v = 1; v <= 5; v++) frequencyTable[v] = 0;
    for (const v of values) frequencyTable[v] = (frequencyTable[v] || 0) + 1;
    for (const key in frequencyTable) {
      percentageTable[key] = totalResponses > 0 ? round2((frequencyTable[key] / totalResponses) * 100) : 0;
    }
    average = totalResponses > 0 ? round2(values.reduce((a, b) => a + b, 0) / totalResponses) : null;
    min = totalResponses > 0 ? Math.min(...values) : null;
    max = totalResponses > 0 ? Math.max(...values) : null;

    let maxFreq = -1;
    mode = [];
    for (const key in frequencyTable) {
      if (frequencyTable[key] > maxFreq) {
        maxFreq = frequencyTable[key];
        mode = [Number(key)];
      } else if (frequencyTable[key] === maxFreq && maxFreq > 0) {
        mode.push(Number(key));
      }
    }
  }

  output.push({
    json: {
      questionId: question.id,
      questionText: question.text,
      type: type,
      totalResponses,
      frequencyTable,
      percentageTable,
      average,
      mode,
      min,
      max,
    }
  });
}

return output;

return [{
  json: {
    surveyId: $('Webhook').first().json.body.surveyId,
    responseId: $('Webhook').first().json.body.responseId,
    status: 'COMPLETADO',
    results: $json.results,
  }
}];

return [{
  json: {
    surveyId: $('Webhook').first().json.body.surveyId,
    responseId: $('Webhook').first().json.body.responseId,
    status: 'FALLIDO',
    errorMessage: $json.error?.message || $json.message || 'Error desconocido en el procesamiento',
  }
}];
